-- 040_vaulting.sql
-- Equestrian vaulting: three ready-made plans filed with the endurance plans,
-- in French, English and German (getting started in 8 weeks, compulsories
-- and freestyle in 12 weeks, conditioning without a horse), and eight
-- exercises a vaulter trains off the horse. Sessions on the horse or the
-- barrel are timed sessions of the sport vaulting.
--
-- Deploy: apply this file first, then the code. The plans name the new
-- exercises, which the library must hold.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO exercises (user_id, name, muscle_group, equipment, is_custom, description, name_fr, name_de, description_fr, description_de)
SELECT NULL, v.name, v.muscle_group, v.equipment, false, v.description, v.name_fr, v.name_de, v.description_fr, v.description_de
FROM (VALUES
  ('Handstand Hold', 'shoulders', 'bodyweight', 'Facing a wall or with your back to it, hands shoulder-width apart, body straight and tight. Hold.', 'Appui tendu renversé (ATR) au mur', 'Handstand an der Wand', 'Face au mur ou dos au mur, mains largeur d’épaules, corps droit et gainé. Tenir.', 'Mit dem Gesicht oder dem Rücken zur Wand, Hände schulterbreit, Körper gerade und fest. Halten.'),
  ('Single-Leg Balance', 'legs', 'bodyweight', 'Stand on one leg, the other knee raised, eyes fixed on a point. Harder with eyes closed or on a cushion.', 'Équilibre sur une jambe', 'Einbeinstand', 'Sur une jambe, l’autre genou levé, le regard fixé sur un point. Plus dur les yeux fermés ou sur un coussin.', 'Auf einem Bein, das andere Knie angehoben, Blick auf einen Punkt. Schwerer mit geschlossenen Augen oder auf einem Kissen.'),
  ('Arabesque Hold', 'legs', 'bodyweight', 'On one leg, lean forward and raise the other leg behind you to hip height, arms out. Hold, back long.', 'Arabesque (équilibre)', 'Standwaage', 'Sur une jambe, pencher le buste et monter l’autre jambe derrière à hauteur de hanche, bras ouverts. Tenir, dos long.', 'Auf einem Bein den Oberkörper neigen und das andere Bein hinten auf Hüfthöhe heben, Arme seitlich. Halten, Rücken lang.'),
  ('Superman Hold', 'back', 'bodyweight', 'Face down, raise the arms and legs off the floor, glutes tight, neck long. Hold.', 'Superman (gainage dorsal)', 'Superman', 'Sur le ventre, décoller bras et jambes du sol, fessiers serrés, nuque longue. Tenir.', 'In Bauchlage Arme und Beine anheben, Gesäß angespannt, Nacken lang. Halten.'),
  ('Tuck Jump', 'legs', 'bodyweight', 'Jump and pull both knees up to the chest, then land softly on the balls of the feet.', 'Sauts groupés', 'Hocksprünge', 'Sauter en ramenant les deux genoux vers la poitrine, puis se réceptionner en douceur sur l’avant des pieds.', 'Springen und beide Knie zur Brust ziehen, dann weich auf den Fußballen landen.'),
  ('Bridge Hold', 'back', 'bodyweight', 'On your back, hands by the ears, push up to an arch, arms and legs as straight as possible. Hold.', 'Pont', 'Brücke', 'Sur le dos, mains près des oreilles, pousser jusqu’au pont, bras et jambes le plus tendus possible. Tenir.', 'In Rückenlage, Hände neben den Ohren, in die Brücke drücken, Arme und Beine möglichst gestreckt. Halten.'),
  ('Front Split Stretch', 'legs', 'bodyweight', 'One leg forward, the other back, hips square. Go down slowly with blocks under the hands; never force.', 'Grand écart avant (progressif)', 'Spagat vorwärts (schrittweise)', 'Une jambe devant, l’autre derrière, bassin de face. Descendre doucement avec des cales sous les mains, sans jamais forcer.', 'Ein Bein vorne, eines hinten, Hüfte gerade. Langsam absenken, mit Blöcken unter den Händen, nie erzwingen.'),
  ('Pike Stretch', 'legs', 'bodyweight', 'Seated, legs together and straight, fold forward at the hips with a long back. Breathe and relax.', 'Pince assise (jambes tendues)', 'Hechtdehnung im Sitzen', 'Assis, jambes serrées et tendues, se pencher depuis les hanches, dos long. Respirer et relâcher.', 'Im Sitzen, Beine geschlossen und gestreckt, aus der Hüfte nach vorn beugen, Rücken lang. Atmen und lösen.')
) AS v(name, muscle_group, equipment, description, name_fr, name_de, description_fr, description_de)
WHERE NOT EXISTS (SELECT 1 FROM exercises e WHERE e.user_id IS NULL AND e.name = v.name);

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Voltige : débuter en 8 semaines', 'Pour découvrir la voltige en club : les imposés appris d’abord sur le tonneau, puis à cheval au pas et au galop, et une séance de préparation physique. Trois séances par semaine. Les séances à cheval se font toujours avec un longeur qualifié.', 'endurance', 'beginner', 3, false, '[{"name":"S1 · Tonneau","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Apprendre les positions des imposés en sécurité, sans le mouvement du cheval.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Montée, Assis de base, Drapeau. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S1 · À cheval","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Pas","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au pas : montée avec l’aide du longeur, puis Assis de base, Drapeau, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S1 · Prépa physique","week":1,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"S2 · Tonneau","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Apprendre les positions des imposés en sécurité, sans le mouvement du cheval.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Assis de base, Drapeau, Moulin. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S2 · À cheval","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Pas","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au pas : montée avec l’aide du longeur, puis Assis de base, Drapeau, Moulin, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S2 · Prépa physique","week":2,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"S3 · Tonneau","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Apprendre les positions des imposés en sécurité, sans le mouvement du cheval.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Moulin, Ciseaux avant. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Enchaînement : Moulin, Ciseaux avant à la suite, 3 fois, sans poser le pied","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S3 · À cheval","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Pas","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au pas : montée avec l’aide du longeur, puis Moulin, Ciseaux avant, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S3 · Prépa physique","week":3,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"S4 · Tonneau","week":4,"exercises":[],"cardio":{"sport":"vaulting","durationMin":35,"intensity":"Technique","purpose":"Semaine plus légère : réviser les figures sans fatigue.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Assis de base, Drapeau, Moulin, Ciseaux avant. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Enchaînement : Assis de base, Drapeau, Moulin, Ciseaux avant à la suite, 3 fois, sans poser le pied","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S4 · À cheval","week":4,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Pas","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au pas : montée avec l’aide du longeur, puis Assis de base, Drapeau, Moulin, Ciseaux avant, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S4 · Prépa physique","week":4,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"S5 · Tonneau","week":5,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Monter en difficulté : le debout et la planche, d’abord sur le tonneau.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Ciseaux arrière, Debout. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Enchaînement : Ciseaux arrière, Debout à la suite, 3 fois, sans poser le pied","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S5 · À cheval","week":5,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Galop","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au galop (au pas tant que le longeur ne vous juge pas prêt) : montée, puis Ciseaux arrière, Debout, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S5 · Prépa physique","week":5,"exercises":[{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"45s","restSec":30}]},{"name":"S6 · Tonneau","week":6,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Monter en difficulté : le debout et la planche, d’abord sur le tonneau.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Debout, Planche. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Enchaînement : Debout, Planche à la suite, 3 fois, sans poser le pied","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S6 · À cheval","week":6,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Galop","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au galop (au pas tant que le longeur ne vous juge pas prêt) : montée, puis Debout, Planche, 2 passages par figure","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S6 · Prépa physique","week":6,"exercises":[{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"45s","restSec":30}]},{"name":"S7 · Tonneau","week":7,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technique","purpose":"Enchaîner les imposés avec fluidité, comme en compétition.","steps":["Échauffement : 5 min de course légère, cercles de bras et de hanches, 10 sauts sur place","Technique : Assis de base, Drapeau, Moulin, Ciseaux avant, Ciseaux arrière, Debout, Planche. 5 fois chacune, tenue sur 4 temps comptés, avec une parade si besoin","Enchaînement : Assis de base, Drapeau, Moulin, Ciseaux avant, Ciseaux arrière, Debout, Planche à la suite, 3 fois, sans poser le pied","Retour au calme : 5 min d’étirements des ischios, des épaules et des hanches"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S7 · À cheval","week":7,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Galop","purpose":"Retrouver à cheval ce qui a été appris sur le tonneau, en suivant le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval sur le cercle, puis mobilité des épaules et des hanches","Au galop (au pas tant que le longeur ne vous juge pas prêt) : montée, puis Assis de base, Drapeau, Moulin, Ciseaux avant, Ciseaux arrière, Debout, Planche, 2 passages par figure","Les imposés enchaînés une fois en entier","Sortie contrôlée, réception pieds joints et genoux fléchis, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S7 · Prépa physique","week":7,"exercises":[{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front 