"targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":3,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"45s","restSec":30}]}]'::jsonb, true, 300, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Voltige : débuter en 8 semaines' AND locale = 'fr');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Voltige : imposés et libre en 12 semaines', 'Pour les voltigeurs qui connaissent les imposés au galop et préparent une compétition : précision des imposés, construction du libre sur le tonneau, force, gainage, souplesse et équilibre. Quatre séances par semaine en quatre phases, avec un affûtage la dernière semaine.', 'endurance', 'intermediate', 4, false, '[{"name":"S1 · À cheval : imposés","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":40,"intensity":"Galop","purpose":"Gagner en précision : des tenues nettes, dans le rythme du cheval.","steps":["Échauffement au sol : 3 tours de course à côté du cheval, puis 5 min de mobilité","Imposés un par un : Assis de base, Drapeau, Moulin, Ciseaux avant, Ciseaux arrière, Debout, Planche. 2 passages chacun, en comptant les foulées de tenue","Sortie contrôlée, puis 5 min d’étirements"],"notes":"Toujours avec un longeur qualifié et un cheval de voltige, en tenue près du corps et chaussons de voltige."}},{"name":"S1 · Tonneau : libre","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":50,"intensity":"Technique","purpose":"Construire le libre : choisir et apprendre ses figures sur le tonneau.","steps":["Échauffement : 5 min de corde à sauter ou de course, mobilité, 2 roulades avant et 2 arrière","Figures du libre : 4 à 6 figures (statiques, dynamiques, assises et debout), 5 fois chacune avec parade","Imposés sur le tonneau : les 2 figures les moins sûres, 5 fois chacune","Retour au calme : 5 min d’étirements"],"notes":"Le tonneau (ou cheval d’arçons) se travaille sur un tapis, avec une parade pour les nouvelles figures."}},{"name":"S1 · Force et gainage","week":1,"exercises":[{"exerciseName":"Handstand Hold","targetSets":3,"targetReps":"15-20s","restSec":60},{"exerciseName":"Pull-up","targetSets":3,"targetReps":"4-6","restSec":90},{"exerciseName":"Push-up","targetSets":3,"targetReps":"10-15","restSec":60},{"exerciseName":"Hanging Leg Raise","targetSets":3,"targetReps":"8-12","restSec":60}