SELECT 'Conditioning for vaulters', 'Two sessions without a horse, at home or at the gym: core, arm and leg strength, balance and flexibility, the qualities behind clean figures. Alongside your club sessions.', 'endurance', 'beginner', 2, true, '[{"name":"Strength and core","exercises":[{"exerciseName":"Handstand Hold","targetSets":3,"targetReps":"15-30s","restSec":60},{"exerciseName":"Push-up","targetSets":3,"targetReps":"8-12","restSec":60},{"exerciseName":"Hollow Hold","targetSets":3,"targetReps":"20-30s","restSec":45},{"exerciseName":"Side Plank","targetSets":3,"targetReps":"30s","restSec":45},{"exerciseName":"Tuck Jump","targetSets":3,"targetReps":"6-8","restSec":60},{"exerciseName":"Bulgarian Split Squat","targetSets":3,"targetReps":"8-10","restSec":90},{"exerciseName":"Superman Hold","targetSets":3,"targetReps":"30s","restSec":45}]},{"name":"Flexibility and balance","exercises":[{"exerciseName":"Front Split Stretch","targetSets":3,"targetReps":"45s","restSec":30},{"exerciseName":"Pike Stretch","targetSets":3,"targetReps":"45s","restSec":30},{"exerciseName":"Bridge Hold","targetSets":3,"targetReps":"15-20s","restSec":45},{"exerciseName":"Arabesque Hold","targetSets":3,"targetReps":"20-30s","restSec":30},{"exerciseName":"Single-Leg Balance","targetSets":3,"targetReps":"30s","restSec":30},{"exerciseName":"Bird Dog","targetSets":3,"targetReps":"10-12","restSec":45}]}]'::jsonb, true, 320, 'en'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Conditioning for vaulters' AND locale = 'en');

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Voltigieren: Einstieg in 8 Wochen', 'Voltigieren im Verein entdecken: die Pflichtübungen zuerst auf dem Holzpferd, dann auf dem Pferd im Schritt und im Galopp, dazu eine Athletikeinheit. Drei Einheiten pro Woche. Auf dem Pferd immer mit einem qualifizierten Longenführer.', 'endurance', 'beginner', 3, false, '[{"name":"W1 · Holzpferd","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technik","purpose":"Die Positionen der Pflicht sicher lernen, ohne die Bewegung des Pferdes.","steps":["Aufwärmen: 5 Min. lockeres Laufen, Arm- und Hüftkreisen, 10 Sprünge auf der Stelle","Technik: Aufsprung, Grundsitz, Fahne. Je 5 Mal, 4 gezählte Takte halten, bei Bedarf mit Hilfestellung","Ausklang: 5 Min. Dehnen von Beinrückseite, Schultern und Hüften"],"notes":"Auf dem Holzpferd über einer Matte üben, neue Figuren mit Hilfestellung."}},{"name":"W1 · Auf dem Pferd","week":1,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Schritt","purpose":"Auf dem Pferd wiederfinden, was auf dem Holzpferd gelernt wurde, im Rhythmus des Pferdes.","steps":["Aufwärmen am Boden: 3 Runden neben dem Pferd auf dem Zirkel laufen, dann Schulter- und Hüftmobilisation","Im Schritt: Aufsprung mit Hilfe des Longenführers, dann Grundsitz, Fahne, 2 Durchgänge pro Figur","Kontrollierter Abgang, Landung mit geschlossenen Füßen und gebeugten Knien, dann 5 Min. Dehnen"],"notes":"Immer mit einem qualifizierten Longenführer und einem Voltigierpferd, in eng anliegender Kleidung und Voltigierschuhen."}},{"name":"W1 · Athletik","week":1,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W2 · Holzpferd","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technik","purpose":"Die Positionen der Pflicht sicher lernen, ohne die Bewegung des Pferdes.","steps":["Aufwärmen: 5 Min. lockeres Laufen, Arm- und Hüftkreisen, 10 Sprünge auf der Stelle","Technik: Grundsitz, Fahne, Mühle. Je 5 Mal, 4 gezählte Takte halten, bei Bedarf mit Hilfestellung","Ausklang: 5 Min. Dehnen von Beinrückseite, Schultern und Hüften"],"notes":"Auf dem Holzpferd über einer Matte üben, neue Figuren mit Hilfestellung."}},{"name":"W2 · Auf dem Pferd","week":2,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Schritt","purpose":"Auf dem Pferd wiederfinden, was auf dem Holzpferd gelernt wurde, im Rhythmus des Pferdes.","steps":["Aufwärmen am Boden: 3 Runden neben dem Pferd auf dem Zirkel laufen, dann Schulter- und Hüftmobilisation","Im Schritt: Aufsprung mit Hilfe des Longenführers, dann Grundsitz, Fahne, Mühle, 2 Durchgänge pro Figur","Kontrollierter Abgang, Landung mit geschlossenen Füßen und gebeugten Knien, dann 5 Min. Dehnen"],"notes":"Immer mit einem qualifizierten Longenführer und einem Voltigierpferd, in eng anliegender Kleidung und Voltigierschuhen."}},{"name":"W2 · Athletik","week":2,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W3 · Holzpferd","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":45,"intensity":"Technik","purpose":"Die Positionen der Pflicht sicher lernen, ohne die Bewegung des Pferdes.","steps":["Aufwärmen: 5 Min. lockeres Laufen, Arm- und Hüftkreisen, 10 Sprünge auf der Stelle","Technik: Mühle, Schere vorwärts. Je 5 Mal, 4 gezählte Takte halten, bei Bedarf mit Hilfestellung","Verbindung: Mühle, Schere vorwärts hintereinander, 3 Mal, ohne den Boden zu berühren","Ausklang: 5 Min. Dehnen von Beinrückseite, Schultern und Hüften"],"notes":"Auf dem Holzpferd über einer Matte üben, neue Figuren mit Hilfestellung."}},{"name":"W3 · Auf dem Pferd","week":3,"exercises":[],"cardio":{"sport":"vaulting","durationMin":30,"intensity":"Schritt","purpose":"Auf dem Pferd wiederfinden, was auf dem Holzpferd gelernt wurde, im Rhythmus des Pferdes.","steps":["Aufwärmen am Boden: 3 Runden neben dem Pferd auf dem Zirkel laufen, dann Schulter- und Hüftmobilisation","Im Schritt: Aufsprung mit Hilfe des Longenführers, dann Mühle, Schere vorwärts, 2 Durchgänge pro Figur","Kontrollierter Abgang, Landung mit geschlossenen Füßen und gebeugten Knien, dann 5 Min. Dehnen"],"notes":"Immer mit einem qualifizierten Longenführer und einem Voltigierpferd, in eng anliegender Kleidung und Voltigierschuhen."}},{"name":"W3 · Athletik","week":3,"exercises":[{"exerciseName":"Plank","targetSets":2,"targetReps":"20-30s","restSec":45},{"exerciseName":"Hollow Hold","targetSets":2,"targetReps":"15-20s","restSec":45},{"exerciseName":"Superman Hold","targetSets":2,"targetReps":"20s","restSec":45},{"exerciseName":"Single-Leg Balance","targetSets":2,"targetReps":"30s","restSec":30},{"exerciseName":"Glute Bridge","targetSets":2,"targetReps":"12-15","restSec":60},{"exerciseName":"Push-up","targetSets":2,"targetReps":"5-8","restSec":60},{"exerciseName":"Front Split Stretch","targetSets":2,"targetReps":"30s","restSec":30}]},{"name":"W4 · Holzpferd","week":4,"exercises":[],"cardio":{"sport":"vaulting","durationMin":35,"intensi